from __future__ import annotations

import base64
import gzip
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "data" / "weekly-patterns"
PAYLOAD = """"""


def main() -> int:
    reports = json.loads(gzip.decompress(base64.b64decode(PAYLOAD)).decode("utf-8"))
    OUT.mkdir(parents=True, exist_ok=True)

    for key, report in reports.items():
        (OUT / f"{key}.json").write_text(
            json.dumps(report, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )

    index_path = OUT / "index.json"
    index = json.loads(index_path.read_text(encoding="utf-8"))
    new_keys = set(reports)
    entries = [item for item in index.get("reports", []) if item.get("key") not in new_keys]
    for key, report in reports.items():
        entries.append({
            "key": key,
            "startDate": report["startDate"],
            "endDate": report["endDate"],
            "title": report["title"],
            "generatedAt": report["generatedAt"],
            "analysisMethod": report["analysisMethod"],
            "periodType": report.get("periodType", "weekly"),
        })
    entries.sort(key=lambda item: item["startDate"])
    latest_key = max(reports, key=lambda key: reports[key]["endDate"])
    index = {
        "updatedAt": reports[latest_key]["generatedAt"],
        "latestKey": latest_key,
        "reports": entries,
    }
    index_path.write_text(json.dumps(index, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    (OUT / "latest.json").write_text(
        json.dumps(reports[latest_key], ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )

    print(json.dumps({
        "keys": sorted(reports),
        "latestKey": latest_key,
        "reportCount": len(entries),
    }, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
